processing_time = [
    [5, 4, 3],
    [6, 5, 4],
    [7, 6, 5],
]
n = len(processing_time)
m = len(processing_time[0])
horizon = sum(sum(row) for row in processing_time)
big_m = max(horizon, n) + 1

prob = pulp.LpProblem("Permutation_Flow_Shop", pulp.LpMinimize)

start = [
    [pulp.LpVariable(f"start_{i}_{j}", 0, horizon, "Continuous")
     for j in range(m)]
    for i in range(n)
]
finish = [
    [pulp.LpVariable(f"finish_{i}_{j}", 0, horizon, "Continuous")
     for j in range(m)]
    for i in range(n)
]
rank = [
    pulp.LpVariable(f"rank_{i}", 1, n, "Integer")
    for i in range(n)
]
before = {}
for i in range(n):
    for k in range(i + 1, n):
        before[i, k] = pulp.LpVariable(f"before_{i}_{k}", cat="Binary")

makespan = pulp.LpVariable("makespan", 0, horizon, "Continuous")

# Processing precedence, elapsed time, and makespan.
for i in range(n):
    for j in range(m):
        prob += finish[i][j] == start[i][j] + processing_time[i][j]
        prob += makespan >= finish[i][j]
        if j + 1 < m:
            prob += start[i][j + 1] >= finish[i][j]

# The same before variable is used on every machine, so the product
# permutation is identical on all three machines.
for i in range(n):
    for k in range(i + 1, n):
        for j in range(m):
            prob += (
                start[k][j]
                >= finish[i][j] - big_m * (1 - before[i, k])
            )
            prob += (
                start[i][j]
                >= finish[k][j] - big_m * before[i, k]
            )

