# upper bound and big-M value.
machine_available = [0.0] * n_vats
for i in range(n_jobs):
    job_available = 0.0
    for j in range(n_vats):
        start = max(machine_available[j], job_available)
        finish = start + processing_times[i][j]
        machine_available[j] = finish
        job_available = finish
horizon = max(machine_available) + 1.0

prob = pulp.LpProblem("Dyeing_Flow_Shop", pulp.LpMinimize)

