    [
        pulp.LpVariable(f"start_{i}_{j}", lowBound=0.0, cat=pulp.LpContinuous)
        for j in range(n_vats)
    ]
    for i in range(n_jobs)
]

before = {}
for j in range(n_vats):
    for i in range(n_jobs):
        for k in range(i + 1, n_jobs):
            before[i, k, j] = pulp.LpVariable(
                f"before_{i}_{k}_{j}", cat=pulp.LpBinary
            )

makespan = pulp.LpVariable("makespan", lowBound=0.0, cat=pulp.LpContinuous)

# Each batch must pass through the vats in the required order.
for i in range(n_jobs):
    for j in range(n_vats - 1):
        prob += (
            start[i][j + 1]
            >= start[i][j] + processing_times[i][j]
        )

# Disjunctive constraints prevent simultaneous dyeing in the same vat.
for j in range(n_vats):
    for i in range(n_jobs):
        for k in range(i + 1, n_jobs):
            b = before[i, k, j]
