                start[k][j]
                >= start[i][j] + processing_times[i][j] - horizon * (1 - b)
            )
            prob += (
                start[i][j]
                >= start[k][j] + processing_times[k][j] - horizon * b
            )

# All operations must fit within the established feasible horizon.
for i in range(n_jobs):
    for j in range(n_vats):
        prob += start[i][j] + processing_times[i][j] <= horizon

# The makespan is the completion time of every batch in the final vat.
for i in range(n_jobs):
    prob += (
