        f"Warehouse_Area_Month_{month}",
    )

prob += pulp.lpSum(
    contract_fee[length] * x[start, length]
    for start in range(1, 5)
    for length in range(1, 5)
)

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

print(
    f"STATUS={pulp.LpStatus[prob.status]} "
    f"OBJECTIVE={pulp.value(prob.objective)}"
)
